function inventoryRows(list) { return list.length ? list.map(p => `<tr><td><b>${esc(p.name)}</b><br><small>${esc(p.category)}</small></td><td class="${+p.stockQty < 12 ? 'low' : ''}">${p.stockQty} units</td><td><input class="qty-input" data-inventory-stock-id="${p.id}" id="stock-${p.id}" type="number" min="0" value="${p.stockQty}"></td><td><label class="product-active-switch" title="${p.active !== false ? 'Product is active' : 'Product is inactive'}"><input data-inventory-active-id="${p.id}" type="checkbox" ${p.active !== false ? 'checked' : ''} onchange="toggleInventoryProduct(${p.id}, this.checked)" aria-label="Set ${esc(p.name)} as active or inactive"><span aria-hidden="true"></span><b>${p.active !== false ? 'Active' : 'Inactive'}</b></label></td><td><button data-inventory-stock-save-id="${p.id}" class="secondary" onclick="saveStock(${p.id})">Update</button></td></tr>`).join('') : '<tr><td colspan="5" class="empty">No products match your search.</td></tr>' }
function inventoryPage() { const allProducts = products(); shell('Inventory management', 'Update stock and quickly identify products that need attention', `<section class="panel"><div class="panel-head inventory-panel-head"><div><h2>Stock levels</h2><span class="low">${allProducts.filter(p => +p.stockQty < 12).length} low stock alerts</span></div><div class="inventory-search-box"><input id="inventory-search" type="search" placeholder="Search products" aria-label="Search inventory products"><button id="inventory-search-button" type="button" aria-label="Search products"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6"></circle><path d="m16 16 4 4"></path></svg></button></div></div><div class="table-wrap"><table class="inventory-table"><thead><tr><th>Product</th><th>Available</th><th>Update quantity</th><th>Active / Inactive</th><th>Action</th></tr></thead><tbody id="inventory-rows">${inventoryRows(allProducts)}</tbody></table></div></section>`); const input = A('#inventory-search'), rows = A('#inventory-rows'), filter = () => { const query = input.value.trim().toLowerCase(); rows.innerHTML = inventoryRows(allProducts.filter(product => !query || `${product.name || ''} ${product.category || ''} ${product.unit || ''}`.toLowerCase().includes(query))); }; input.addEventListener('input', filter); A('#inventory-search-button').addEventListener('click', () => { input.focus(); filter(); }); }
function saveStock(id) { let ps = products(), p = ps.find(x => x.id === id), value = +A('#stock-' + id).value; p.stockQty = Math.max(0, value); p.stock = p.stockQty > 0; set('dc_products', ps); toast('Inventory updated') }
