function billingPage() { let ps = products(); shell('Offline billing', 'Create a bill for walk-in customers and save it as an order', `<section class="panel billing"><div class="form-grid"><label>Customer name<input id="bill-name" placeholder="Walk-in customer"></label><label>Phone number<input id="bill-phone" placeholder="Optional"></label><label>Product<select id="bill-product">${ps.map(p => `<option value="${p.id}">${esc(p.name)} — ${money(p.price)}</option>`).join('')}</select></label><label>Quantity<input id="bill-qty" type="number" min="1" value="1"></label></div><div class="form-actions"><button class="secondary" onclick="addBillItem()">Add item</button></div><div id="bill-items" class="empty">No products added to this bill.</div><div class="form-actions"><button class="primary" onclick="createBill()">Create & save bill</button></div></section>`); window.bill = [] }
