function createBill() { if (!window.bill?.length) { toast('Add at least one product'); return } let total = window.bill.reduce((s, x) => s + products().find(p => p.id === x.id).price * x.qty, 0), os = orders(); os.unshift({ id: 'OFF-' + Date.now().toString().slice(-6), items: window.bill, total, payment: 'Offline / Cash', status: 'Delivered', placedAt: new Date().toISOString(), customer: { name: A('#bill-name').value || 'Walk-in customer', phone: A('#bill-phone').value } }); set('dc_orders', os); toast('Offline bill saved'); billingPage() }
