function reportsPage() { let os = orders(), now = Date.now(), sum = ms => os.filter(o => now - new Date(o.placedAt || 0).getTime() <= ms).reduce((s, o) => s + +o.total, 0); shell('Reports & summary', 'Daily, weekly, and monthly sales information', `<div class="stats"><article class="stat"><span>Today</span><strong>${money(sum(86400000))}</strong></article><article class="stat"><span>This week</span><strong>${money(sum(604800000))}</strong></article><article class="stat"><span>This month</span><strong>${money(sum(2592000000))}</strong></article><article class="stat"><span>All-time sales</span><strong>${money(os.reduce((s, o) => s + +o.total, 0))}</strong></article></div><section class="panel"><div class="panel-head"><h2>Sales report</h2><span>${os.length} total orders</span></div>${orderTable(os.slice(0, 12))}</section>`) }
function normalizeBulkText(value) { return String(value ?? '').trim(); }
function parseBulkNumber(value) { if (value === null || value === undefined || value === '') return null; const text = String(value).trim(); if (/^true$/i.test(text) || /^yes$/i.test(text) || /^available$/i.test(text) || /^in stock$/i.test(text)) return 1; const cleaned = text.replace(/,/g, '').replace(/[^0-9.-]/g, ''); if (cleaned === '') return null; const num = Number(cleaned); return Number.isFinite(num) ? num : null; }
function normalizeBulkKey(product) { return `${String(product.category || '').trim().toLowerCase()}|${String(product.name || '').trim().toLowerCase()}|${String(product.unit || '').trim().toLowerCase()}`; }
function buildBulkTemplate() { if (!window.XLSX) { toast('Spreadsheet support is still loading. Please try again.'); return } const ws = XLSX.utils.aoa_to_sheet([["Image URL", "Product Name", "Category", "Quantity", "Unit", "Stock", "Maximum Buying Limit", "Minimum Buying Limit", "MRP", "Price", "Discount (rs)", "Barcode"]]); const guide = XLSX.utils.aoa_to_sheet([["Bulk upload instructions"], ["Fill one product per row in the Products sheet."], ["Leave Maximum Buying Limit blank to keep the maximum limit OFF."], ["Leave Minimum Buying Limit blank to keep the minimum limit OFF."], ["Enter a numeric limit only when you want that limit to be ON."], ["Enter MRP and Discount to calculate Price automatically, or MRP and Price to calculate Discount automatically."], ["Units can include kg, g, L, dozen, piece, or pack."]]); const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, ws, 'Products'); XLSX.utils.book_append_sheet(wb, guide, 'Instructions'); XLSX.writeFile(wb, 'delhi-canteen-bulk-upload-template.xlsx'); }
function downloadBulkTemplate() { buildBulkTemplate(); }
function productExportPack(unit) {
  const value = String(unit ?? '').trim();
  const match = value.match(/^([\d.]+)\s*(.*)$/);
  if (match) return { quantity: match[1], unit: match[2].trim() || 'piece' };
  return { quantity: '1', unit: value || 'piece' };
}
function productExportCsv(rows, headers) {
  const cell = value => `"${String(value ?? '').replace(/"/g, '""')}"`;
  const csv = '\ufeff' + [headers, ...rows.map(row => headers.map(header => row[header]))].map(row => row.map(cell).join(',')).join('\r\n');
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
  const link = document.createElement('a');
  link.href = url;
  link.download = 'delhi-canteen-products.csv';
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}
function downloadProductExport(content, fileName, type) {
  const url = URL.createObjectURL(new Blob([content], { type }));
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  link.style.display = 'none';
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
function exportProductsToExcel() {
  const headers = ['Image URL', 'Product Name', 'Category', 'Quantity', 'Unit', 'Stock', 'Maximum Buying Limit', 'Minimum Buying Limit', 'MRP', 'Price', 'Discount (rs)', 'Barcode'];
  const barcodes = get('dc_product_barcodes', {});
  const rows = products().map(product => {
    const pack = productExportPack(product.unit);
    const mrp = Number(product.mrp) || 0;
    const price = Number(product.price) || 0;
    const savedDiscount = Number(product.discount);
    return {
      'Image URL': product.image || '',
      'Product Name': product.name || '',
      'Category': product.category || '',
      'Quantity': pack.quantity,
      'Unit': pack.unit,
      'Stock': Number(product.stockQty ?? 0),
      'Maximum Buying Limit': product.maxLimitEnabled === true ? Number(product.maxBuy) || 1 : '',
      'Minimum Buying Limit': product.minLimitEnabled === true ? Number(product.minBuy) || 1 : '',
      'MRP': mrp,
      'Price': price,
      'Discount (rs)': Number.isFinite(savedDiscount) ? savedDiscount : Math.max(0, mrp - price),
      'Barcode': barcodes[product.apiId] ?? product.productCode ?? ''
    };
  });
  if (!rows.length) { toast('There are no products to export'); return; }
  if (!window.XLSX) {
    productExportCsv(rows, headers);
    toast('Excel library was unavailable, so a CSV file was downloaded. It opens directly in Excel.');
    return;
  }
  try {
    const sheet = XLSX.utils.json_to_sheet(rows, { header: headers });
    sheet['!cols'] = [
      { wch: 42 }, { wch: 28 }, { wch: 22 }, { wch: 11 }, { wch: 13 }, { wch: 10 },
      { wch: 23 }, { wch: 23 }, { wch: 12 }, { wch: 12 }, { wch: 15 }, { wch: 20 }
    ];
    sheet['!autofilter'] = { ref: `A1:L${rows.length + 1}` };
    const book = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(book, sheet, 'Products');
    const excelFile = XLSX.write(book, { bookType: 'xlsx', type: 'array' });
    downloadProductExport(excelFile, 'delhi-canteen-products.xlsx', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    toast(`${rows.length} product${rows.length === 1 ? '' : 's'} exported successfully`);
  } catch (error) {
    console.error('Product export failed:', error);
    productExportCsv(rows, headers);
    toast('Excel file could not be created, so a CSV file was downloaded. It opens in Excel.');
  }
}
