function couponList(){ return get('dc_coupons', []); }
function couponStatus(coupon){ const now=Date.now(); return !coupon.active?'Inactive':now<new Date(coupon.startAt)?'Scheduled':now>new Date(coupon.endAt)?'Expired':'Active'; }
function couponDate(value){ return new Date(value).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}); }
function couponOffer(coupon){ return coupon.type==='percent'?`${coupon.value}% off`:`Rs. ${coupon.value} off`; }
function couponHistory(){ const host=A('#coupon-history'); if(!host)return; const uses=get('dc_coupon_usage',[]); host.innerHTML=couponList().length?`<div class="table-wrap"><table class="coupon-table"><thead><tr><th>Code</th><th>Offer</th><th>Validity</th><th>Customer limit</th><th>Customers used</th><th>Status</th><th>Actions</th></tr></thead><tbody>${couponList().map(coupon=>{const usedCustomers=new Set(uses.filter(use=>use.couponId===coupon.id).map(use=>use.customerId)).size;return `<tr><td><b>${esc(coupon.code)}</b></td><td>${couponOffer(coupon)}</td><td><small>${couponDate(coupon.startAt)}<br>to ${couponDate(coupon.endAt)}</small></td><td>${coupon.limit} customers</td><td>${usedCustomers} / ${coupon.limit}</td><td>${status(couponStatus(coupon))}</td><td><button class="secondary" onclick="openCouponEditor('${coupon.id}')">Update</button> <button class="danger" onclick="deleteCoupon('${coupon.id}')">Delete</button></td></tr>`}).join('')}</tbody></table></div>`:'<p class="empty">No coupons created yet. Create one to make it available to every customer.</p>'; }
function openCouponEditor(id){ const existing=couponList().find(coupon=>coupon.id===id)||{}, toLocal=value=>value?new Date(value).toISOString().slice(0,16):''; modal(`<h2>${id?'Update':'Create'} coupon</h2><form id="coupon-form"><div class="form-grid"><label>Coupon code<input name="code" required maxlength="30" pattern="[A-Za-z0-9_-]+" value="${esc(existing.code||'')}" placeholder="e.g. FESTIVE20"></label><label>Discount type<select name="type"><option value="percent" ${existing.type==='percent'?'selected':''}>Percentage (%)</option><option value="flat" ${existing.type==='flat'?'selected':''}>Flat amount (Rs.)</option></select></label><label>Discount value<input name="value" required type="number" min="1" step="0.01" value="${esc(existing.value||'')}"></label><label>Total customer limit<input name="limit" required type="number" min="1" step="1" value="${esc(existing.limit||1)}"><small>Each customer can use this coupon once.</small></label><label>Starting date & time<input name="startAt" required type="datetime-local" value="${toLocal(existing.startAt)}"></label><label>Ending date & time<input name="endAt" required type="datetime-local" value="${toLocal(existing.endAt)}"></label><label><input name="active" type="checkbox" ${existing.active!==false?'checked':''}> Coupon is active</label></div><div class="form-actions"><button class="secondary" type="button" onclick="closeModal()">Cancel</button><button class="primary" type="submit">${id?'Save changes':'Create coupon'}</button></div></form>`); const form=A('#coupon-form'); form.onsubmit=event=>{event.preventDefault();if(!form.reportValidity())return;const fields=Object.fromEntries(new FormData(form)),code=fields.code.trim().toUpperCase(),startAt=new Date(fields.startAt).toISOString(),endAt=new Date(fields.endAt).toISOString(),value=Number(fields.value),limit=Math.floor(Number(fields.limit));if(new Date(endAt)<=new Date(startAt)){toast('Ending date/time must be after the start');return}if(fields.type==='percent'&&value>100){toast('Percentage discount cannot exceed 100%');return}if(couponList().some(coupon=>coupon.id!==id&&coupon.code.toUpperCase()===code)){toast('This coupon code already exists');return}const coupon={id:id||`CPN-${Date.now()}`,code,type:fields.type,value,limit,startAt,endAt,active:form.elements.active.checked,createdAt:existing.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};set('dc_coupons',id?couponList().map(item=>item.id===id?coupon:item):[coupon,...couponList()]);closeModal();couponHistory();toast(`Coupon ${id?'updated':'created'} and available to all customers`)}; }
function deleteCoupon(id){ const coupon=couponList().find(item=>item.id===id);if(!coupon)return;set('dc_coupons',couponList().filter(item=>item.id!==id));couponHistory();toast('Coupon deleted'); }
window.addEventListener('load',()=>{if(document.body.dataset.page!=='profile')return;const slider=A('.slider-manager');if(!slider||A('.coupon-manager'))return;slider.insertAdjacentHTML('beforebegin','<section class="panel coupon-manager"><div class="panel-head"><div><h2>Coupon codes</h2><p class="muted">Each customer can use a coupon once. Set the maximum number of customers who may use it.</p></div><button class="primary" type="button" onclick="openCouponEditor()">+ Create coupon</button></div><div id="coupon-history"></div></section>');couponHistory();});
