function renderBookingChargeSettings(){const host=A('#booking-charge-settings');if(!host)return;const config=bookingChargeConfig();host.innerHTML=`<form id="booking-charge-settings-form" class="booking-charge-settings"><div><h2>Cash on Delivery booking charge</h2><p class="muted">When enabled, customers selecting Cash on Delivery must pay this amount first by UPI.</p></div><label class="booking-switch"><input name="enabled" type="checkbox" ${config.enabled?'checked':''}><span></span>Booking charge active</label><label class="booking-amount">Booking charge amount (Rs.)<input name="amount" type="number" min="0" step="1" value="${config.amount}" ${config.enabled?'':'disabled'}></label><button class="primary" type="submit">Save booking charge</button></form>`;const form=A('#booking-charge-settings-form');form.elements.enabled.onchange=()=>{form.elements.amount.disabled=!form.elements.enabled.checked};form.onsubmit=event=>{event.preventDefault();const enabled=form.elements.enabled.checked,amount=Math.max(0,Number(form.elements.amount.value)||0);if(enabled&&amount<=0){toast('Enter a booking charge greater than Rs. 0');form.elements.amount.focus();return}set('dc_booking_charge_settings',{...get('dc_booking_charge_settings',{}),enabled,amount});toast(enabled?`Booking charge set to ${money(amount)} for Cash on Delivery`:'Booking charge turned off');renderBookingChargeSettings()};}
