function renderOnlinePaymentSettings(){const host=A('#online-payment-settings');if(!host)return;const config=onlinePaymentConfig(),hasQr=Boolean(config.qrCodeUrl);host.innerHTML=`<form id="online-payment-settings-form" class="online-payment-settings"><div><h2>Online payment QR code</h2><p class="muted">This QR code is shown when a customer selects Online Payment at checkout.</p></div><label>UPI ID<input name="upiId" value="${esc(config.upiId)}" placeholder="e.g. canteen@upi"></label><label>Upload payment QR<span class="payment-file-picker"><input name="qrCode" type="file" accept="image/png,image/jpeg,image/webp"><span class="payment-file-button">Choose File</span>${hasQr?'':'<small class="payment-file-empty">No file chosen</small>'}</span></label>${hasQr?`<img class="online-payment-qr-preview" src="${esc(config.qrCodeUrl)}" alt="Current payment QR code">`:'<p class="muted online-payment-empty">No QR code uploaded yet.</p>'}<button class="primary" type="submit">Save online payment</button></form>`;const form=A('#online-payment-settings-form');form.elements.qrCode.onchange=event=>{const empty=A('.payment-file-empty',form);if(empty&&event.target.files?.[0])empty.textContent=event.target.files[0].name};form.onsubmit=event=>{event.preventDefault();const file=form.elements.qrCode.files?.[0],save=qrCodeUrl=>{set('dc_online_payment_settings',{upiId:form.elements.upiId.value.trim(),qrCodeUrl});toast('Online payment settings saved');renderOnlinePaymentSettings()};if(!file){save(config.qrCodeUrl);return}if(!file.type.startsWith('image/')||file.size>1500*1024){toast('Upload a JPG, PNG, or WebP QR image smaller than 1.5 MB');return}const reader=new FileReader();reader.onload=()=>save(reader.result);reader.readAsDataURL(file)};}
window.addEventListener('load',()=>{if(document.body.dataset.page!=='profile')return;const coupon=A('.coupon-manager'),slider=A('.slider-manager');const anchor=coupon||slider;if(!anchor||A('#booking-charge-settings'))return;anchor.insertAdjacentHTML('afterend','<section class="panel booking-charge-manager"><div id="booking-charge-settings"></div></section>');renderBookingChargeSettings();});
window.addEventListener('load',()=>{if(document.body.dataset.page!=='profile')return;const booking=A('.booking-charge-manager'),slider=A('.slider-manager'),anchor=booking||slider;if(!anchor||A('#online-payment-settings'))return;anchor.insertAdjacentHTML('afterend','<section class="panel online-payment-manager"><div id="online-payment-settings"></div></section>');renderOnlinePaymentSettings();});

function categoryDemoImage(category) { const name = String(category || '').toLowerCase(); if (/fruit/.test(name)) return 'https://images.unsplash.com/photo-1619566636858-adf3ef46400b?auto=format&fit=crop&w=160&q=80'; if (/vegetable|veg/.test(name)) return 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=160&q=80'; if (/dairy|milk|cheese/.test(name)) return 'https://images.unsplash.com/photo-1628088062854-d1870b4553da?auto=format&fit=crop&w=160&q=80'; if (/drink|beverage|juice|cold/.test(name)) return 'https://images.unsplash.com/photo-1544145945-f90425340c7e?auto=format&fit=crop&w=160&q=80'; if (/bakery|bread|cake/.test(name)) return 'https://images.unsplash.com/photo-1509440159596-0249088772ff?auto=format&fit=crop&w=160&q=80'; if (/snack|chips|namkeen/.test(name)) return 'https://images.unsplash.com/photo-1621939514649-280e2ee25f60?auto=format&fit=crop&w=160&q=80'; if (/rice|grain|flour|atta|dal|pulse/.test(name)) return 'https://images.unsplash.com/photo-1586208958839-06c17cacdf08?auto=format&fit=crop&w=160&q=80'; return 'https://images.unsplash.com/photo-1534723452862-4c874018d66d?auto=format&fit=crop&w=160&q=80'; }

window.addEventListener('load', () => { if (document.body.dataset.page !== 'customers') return; const bar = A('.action-bar'); if (!bar || A('#download-customers-excel')) return; const button = document.createElement('button'); button.id = 'download-customers-excel'; button.className = 'secondary'; button.type = 'button'; button.textContent = 'Download Excel'; bar.append(button); button.onclick = () => { if (!window.XLSX) { toast('Excel support is still loading. Please try again.'); return } const accounts = customerAccounts(), seen = new Set(), rows = []; const add = customer => { if (!customer) return; const key = String(customer.customerId || customer.email || customer.phone || '').toLowerCase(); if (!key || seen.has(key)) return; seen.add(key); rows.push({ 'Name': customer.name || '', 'Phone no': customer.phone || '', 'Email id': customer.email || '', 'password': customer.password || '' }) }; accounts.forEach(add); add(get('dc_user', null)); const sheet = XLSX.utils.json_to_sheet(rows, { header: ['Name', 'Phone no', 'Email id', 'password'] }); const book = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(book, sheet, 'Customers'); XLSX.writeFile(book, 'delhi-canteen-customers.xlsx'); toast(`${rows.length} customer${rows.length === 1 ? '' : 's'} exported successfully`) }; });
window.addEventListener('load', () => { if (document.body.dataset.page !== 'customers') return; const accounts = customerAccounts(), os = orders(), bs = get('dc_offline_bills', []), id = x => String(x?.customerId || x?.id || ''), list = accounts.slice(), count = (arr, c) => arr.filter(x => id(x.customer || x) === id(c)).length; const rows = list.map((c, i) => '<tr><td>' + esc(c.customerId || '—') + '</td><td><b>' + esc(c.name || '—') + '</b></td><td>' + esc(c.email || '—') + '</td><td>' + esc(c.phone || '—') + '</td><td>' + esc(c.password || '—') + '</td><td>' + count(bs, c) + '</td><td>' + count(os, c) + '</td><td><button class="icon-btn" data-edit="' + i + '">Edit</button> <button class="icon-btn" data-delete="' + i + '">Delete</button></td></tr>').join(''); shell('Customers', 'Manage online and manually added customer accounts', '<div class="action-bar"><span>' + list.length + ' customers</span><button class="primary" id="add-customer">+ Add customer</button><button class="secondary" id="download-customers-excel">Download Excel</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Customer ID</th><th>Customer name</th><th>Email ID</th><th>Phone no.</th><th>Password</th><th>Revisit</th><th>Reorder</th><th>Actions</th></tr></thead><tbody>' + rows + '</tbody></table></div></section>'); A('#download-customers-excel').onclick = () => { if (!window.XLSX) { toast('Excel support is still loading'); return } const data = list.map(c => ({ 'Customer ID': c.customerId || '', 'Customer name': c.name || '', 'Email ID': c.email || '', 'Phone no.': c.phone || '', 'Password': c.password || '', 'Revisit': count(bs, c), 'Reorder': count(os, c) })); const ws = XLSX.utils.json_to_sheet(data), wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, ws, 'Customers'); XLSX.writeFile(wb, 'delhi-canteen-customers.xlsx') }; A('#add-customer').onclick = () => { const name = prompt('Customer name'), phone = prompt('Phone no.'), email = prompt('Email ID'), password = prompt('Password (minimum 6 characters)'); if (name && phone && email && password) { set('dc_customers', [{ name, phone, email, password, customerId: allocateCustomerId(), source: 'admin', createdAt: new Date().toISOString() }, ...accounts]); location.reload() } }; document.querySelectorAll('[data-delete]').forEach(b => b.onclick = () => { if (confirm('Delete this customer?')) { set('dc_customers', accounts.filter((_, i) => i !== +b.dataset.delete)); location.reload() } }); document.querySelectorAll('[data-edit]').forEach(b => b.onclick = () => { const c = list[+b.dataset.edit], name = prompt('Customer name', c.name), phone = prompt('Phone no.', c.phone), email = prompt('Email ID', c.email); if (name && phone && email) { set('dc_customers', accounts.map((x, i) => i === +b.dataset.edit ? { ...x, name, phone, email } : x)); location.reload() } }); });

// Category editor: rename a category, optionally replace its image, and keep linked products in sync.
function editCategory(currentName) { const existingImages = get('dc_category_images', {}), formName = String(currentName || ''); modal(`<h2>Edit category</h2><form id="edit-category-form"><div class="form-grid"><label class="full">Category image <small>Choose a new image only if you want to replace the current one.</small><input id="edit-category-image-file" type="file" accept="image/*"></label><label class="full">Name<input name="categoryName" required value="${esc(formName)}"></label></div><div class="form-actions"><button class="secondary" type="button" onclick="closeModal()">Cancel</button><button class="primary">Save changes</button></div></form>`); const form = A('#edit-category-form'); form.onsubmit = event => { event.preventDefault(); const newName = form.categoryName.value.trim(), allNames = [...new Set([...products().map(product => product.category), ...get('dc_categories', [])])]; if (!newName) { form.categoryName.focus(); return } if (newName.toLowerCase() !== formName.toLowerCase() && allNames.some(name => String(name).toLowerCase() === newName.toLowerCase())) { toast('A category with this name already exists'); form.categoryName.focus(); return } const save = image => { set('dc_products', products().map(product => product.category === formName ? { ...product, category: newName } : product)); set('dc_categories', [...new Set(get('dc_categories', []).map(name => name === formName ? newName : name).concat(allNames.includes(newName) ? [] : [newName]))]); const images = { ...existingImages }; if (formName !== newName) { delete images[formName]; } if (image) images[newName] = image; else if (formName !== newName && existingImages[formName]) images[newName] = existingImages[formName]; set('dc_category_images', images); closeModal(); categoriesPage(); toast('Category updated'); }; const file = A('#edit-category-image-file').files[0]; if (file) { const reader = new FileReader(); reader.onload = () => save(reader.result); reader.readAsDataURL(file); } else save(); }; }

window.addEventListener('load', () => { if (document.body.dataset.page !== 'categories') return; categoriesPage = function () { const images = get('dc_category_images', {}), cats = [...new Set([...products().map(product => product.category), ...get('dc_categories', [])])]; shell('Category listing', 'Organize the categories visible in your customer store', `<div class="action-bar"><p>${cats.length} active categories</p><button class="primary" onclick="addCategory()">+ Add category</button></div><section class="panel"><div class="table-wrap"><table class="category-list-table"><thead><tr><th>Image</th><th>Category name</th><th>Products</th><th>View products</th><th>Actions</th></tr></thead><tbody>${cats.map(category => { const items = products().filter(product => product.category === category), image = images[category], encoded = encodeURIComponent(category).replace(/'/g, '%27'); return `<tr><td>${image ? `<img class="category-list-image" src="${esc(image)}" alt="${esc(category)}">` : '<span class="category-list-image category-image-placeholder">No image</span>'}</td><td><b>${esc(category)}</b></td><td>${items.length}</td><td><button class="secondary category-view-button" type="button" onclick="showCategoryItems('${encoded}')">View products</button></td><td><button class="icon-btn" type="button" onclick="editCategory(decodeURIComponent('${encoded}'))">Edit</button><button class="icon-btn category-delete-button" type="button" onclick="removeCategory(decodeURIComponent('${encoded}'))">Delete</button></td></tr>` }).join('')}</tbody></table></div></section>`); }; categoriesPage(); });

const categoryEditor = editCategory;
editCategory = function (currentName) {
  categoryEditor(currentName);
  const form = A('#edit-category-form');
  if (!form) return;

  const moveProduct = async (product, category) => {
    const previousCategory = product.category;
    set('dc_products', products().map(item => String(item.id) === String(product.id) ? { ...item, category } : item));
    set('dc_categories', [...new Set([...get('dc_categories', []), category])]);
    try {
      if (product.apiId && window.adminApi && window.categoryIdByName && localStorage.getItem('dc_admin_token')) {
        const categoryId = await categoryIdByName(category);
        await adminApi(`/products/${product.apiId}`, { method: 'PUT', body: JSON.stringify({ name: product.name, categoryId, unit: product.unit || '1 unit', price: Number(product.price) || 0, mrp: Number(product.mrp) || Number(product.price) || 0, stock: Math.max(0, Number(product.stockQty) || 0), image: product.image || '' }) });
      }
      toast(category === currentName ? 'Product added to this category' : 'Product removed from this category');
      closeModal();
      editCategory(currentName);
    } catch (error) {
      set('dc_products', products().map(item => String(item.id) === String(product.id) ? { ...item, category: previousCategory } : item));
      toast(error.message || 'Could not update the product category');
      closeModal();
      editCategory(currentName);
    }
  };

  const renderProduct = (product, action) => `<div class="category-product-option category-edit-product"><span>${esc(product.name)}<small>${esc(product.unit)} · ${money(product.price)}</small></span><button class="${action === 'add' ? 'primary' : 'danger'} category-${action}-product" type="button" data-product-id="${product.id}">${action === 'add' ? 'Add' : 'Remove'}</button></div>`;
  const currentProducts = products().filter(product => product.category === currentName);
  const picker = document.createElement('section');
  picker.className = 'category-product-picker category-edit-products';
  picker.innerHTML = `<h3>Add products to this category</h3><div class="category-product-search-shell"><input class="category-product-search" type="search" placeholder="Search products to add" aria-label="Search products to add"><button class="category-product-search-button" type="button" aria-label="Search products"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6"></circle><path d="m16 16 4 4"></path></svg></button></div><div class="category-product-options category-add-product-options"></div><h3 class="category-current-products-title">Remove products from this category</h3><div class="category-product-options category-current-product-options">${currentProducts.length ? currentProducts.map(product => renderProduct(product, 'remove')).join('') : '<p class="empty">No products are assigned to this category.</p>'}</div>`;
  const pickerSections = [...picker.children], pickerLayout = document.createElement('div'), addSection = document.createElement('section'), currentSection = document.createElement('section');
  pickerLayout.className = 'category-product-columns';
  addSection.className = 'category-product-column';
  currentSection.className = 'category-product-column';
  pickerSections.slice(0, 3).forEach(element => addSection.append(element));
  pickerSections.slice(3).forEach(element => currentSection.append(element));
  const currentSearch = document.createElement('input');
  currentSearch.className = 'category-current-product-search';
  currentSearch.type = 'search';
  currentSearch.placeholder = 'Search products in this category';
  currentSearch.setAttribute('aria-label', 'Search products in this category');
  const currentSearchShell = document.createElement('div');
  currentSearchShell.className = 'category-current-product-search-shell';
  currentSearchShell.innerHTML = '<button class="category-current-product-search-button" type="button" aria-label="Search products in this category"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6"></circle><path d="m16 16 4 4"></path></svg></button>';
  currentSearchShell.prepend(currentSearch);
  currentSection.querySelector('.category-current-product-options').before(currentSearchShell);
  pickerLayout.append(addSection, currentSection);
  picker.append(pickerLayout);
  form.querySelector('.form-actions').insertAdjacentElement('beforebegin', picker);

  const search = picker.querySelector('.category-product-search');
  const available = products().filter(product => product.category !== currentName);
  const drawCurrent = () => {
    const query = currentSearch.value.trim().toLowerCase();
    const matches = currentProducts.filter(product => !query || `${product.name} ${product.category || ''} ${product.unit || ''}`.toLowerCase().includes(query));
    picker.querySelector('.category-current-product-options').innerHTML = matches.length ? matches.map(product => renderProduct(product, 'remove')).join('') : `<p class="empty">${query ? 'No matching products found.' : 'No products are assigned to this category.'}</p>`;
    picker.querySelectorAll('.category-remove-product').forEach(button => button.onclick = () => moveProduct(products().find(product => String(product.id) === String(button.dataset.productId)), 'Uncategorized'));
  };
  currentSearch.oninput = drawCurrent;
  picker.querySelector('.category-current-product-search-button').onclick = drawCurrent;
  const drawAvailable = () => {
    const query = search.value.trim().toLowerCase();
    const matches = available.filter(product => !query || `${product.name} ${product.category || ''} ${product.unit || ''}`.toLowerCase().includes(query));
    picker.querySelector('.category-add-product-options').innerHTML = matches.length ? matches.map(product => renderProduct(product, 'add')).join('') : `<p class="empty">${query ? 'No matching products found.' : 'All products are already in this category.'}</p>`;
    picker.querySelectorAll('.category-add-product').forEach(button => button.onclick = () => moveProduct(products().find(product => String(product.id) === String(button.dataset.productId)), currentName));
  };
  picker.querySelector('.category-product-search-button').onclick = () => {
    drawAvailable();
    picker.querySelector('.category-add-product-options').scrollIntoView({ block: 'start', behavior: 'smooth' });
  };
  search.oninput = drawAvailable;
  search.onkeydown = event => {
    if (event.key === 'Enter') {
      event.preventDefault();
      picker.querySelector('.category-product-search-button').click();
    }
  };
  drawAvailable();
  drawCurrent();

  form.onsubmit = event => { event.preventDefault(); const newName = form.categoryName.value.trim(), allNames = [...new Set([...products().map(product => product.category), ...get('dc_categories', [])])]; if (!newName) { form.categoryName.focus(); return } if (newName.toLowerCase() !== String(currentName).toLowerCase() && allNames.some(name => String(name).toLowerCase() === newName.toLowerCase())) { toast('A category with this name already exists'); form.categoryName.focus(); return } const save = image => { set('dc_products', products().map(product => product.category === currentName ? { ...product, category: newName } : product)); const savedCategories = get('dc_categories', []).map(name => name === currentName ? newName : name); set('dc_categories', [...new Set([...savedCategories, newName])]); const images = get('dc_category_images', {}); if (currentName !== newName) delete images[currentName]; if (image) images[newName] = image; else if (currentName !== newName && get('dc_category_images', {})[currentName]) images[newName] = get('dc_category_images', {})[currentName]; set('dc_category_images', images); closeModal(); categoriesPage(); toast('Category updated'); }; const file = A('#edit-category-image-file').files[0]; if (file) { const reader = new FileReader(); reader.onload = () => save(reader.result); reader.readAsDataURL(file); } else save(); };
};

window.addEventListener('load', () => { if (document.body.dataset.page !== 'categories') return; const renderCategoriesWithPlaceholders = categoriesPage; categoriesPage = function () { renderCategoriesWithPlaceholders(); A('#admin-app').querySelectorAll('.category-image-placeholder').forEach(placeholder => { const category = placeholder.closest('tr')?.querySelector('td:nth-child(2) b')?.textContent || '', image = document.createElement('img'); image.className = 'category-list-image'; image.src = categoryDemoImage(category); image.alt = category; placeholder.replaceWith(image); }); }; categoriesPage(); });

