// Keep the admin screen unchanged, but format generated receipts for a
// 3-inch (76.2 mm) thermal-printer paper roll.
if (document.body.dataset.page === 'billing') {
  const nativeOpen = window.open.bind(window);
  window.open = (url, target, features = '') => {
    const receiptWindow = nativeOpen(url, target, String(features).replace(/width=\d+/, 'width=320'));
    if (!receiptWindow) return receiptWindow;

    const nativeWrite = receiptWindow.document.write.bind(receiptWindow.document);
    receiptWindow.document.write = markup => {
      const receiptMarkup = String(markup);
      const wholeAmounts = receiptMarkup.replace(/Rs\. (\d+)\.\d{2}/g, 'Rs. $1');
      const normalizedQuantity = wholeAmounts.replace(/(<tr><td>\d+<\/td><td>[\s\S]*?<\/td><td>\d+)\s+1\s+/g, '$1 ');
      const receiptCss = '@page{size:3in auto;margin:0}html,body{width:3in!important;margin:0!important;padding:0!important}body{max-width:none!important;padding:.1in!important;font-size:10px!important}header{padding-bottom:8px!important}h1{font-size:16px!important}table{margin:10px 0!important;font-size:8px!important;table-layout:fixed}th,td{padding:4px 2px!important;overflow-wrap:anywhere}th:first-child,td:first-child{width:6%;padding-left:0!important;padding-right:1px!important}th:nth-child(2),td:nth-child(2){width:32%}th:nth-child(3),td:nth-child(3){width:11%;white-space:nowrap}th:nth-child(4),td:nth-child(4),th:nth-child(6),td:nth-child(6),th:nth-child(7),td:nth-child(7){white-space:nowrap;font-size:7px}th:nth-child(5),td:nth-child(5){width:17%;white-space:nowrap}.total{width:100%!important;font-size:10px!important}.grand{font-size:12px!important}';
      return nativeWrite(normalizedQuantity.includes('<title>Bill ') ? normalizedQuantity.replace('</style>', receiptCss + '</style>') : normalizedQuantity);
    };
    return receiptWindow;
  };
}

if (document.body.dataset.page === 'billing') billingPage();

// Match an entered/scanned barcode immediately and fill the linked product.
window.addEventListener('load', () => {
  if (document.body.dataset.page !== 'billing') return;
  const barcode = A('#pos-barcode');
  if (!barcode) return;
  let barcodeTimer;
  const matchBarcode = (showError = false) => {
    const code = barcode.value.trim().toLowerCase();
    if (!code) return;
    const product = products().find(item => String(item.productCode || item.barcode || '').trim().toLowerCase() === code);
    if (product) {
      barcode.dispatchEvent(new Event('change'));
      return;
    }
    if (showError) {
      window.offlineBillState.productId = null;
      ['pos-product-name', 'pos-category', 'pos-unit', 'pos-mrp', 'pos-price'].forEach(id => A('#' + id).value = '');
      A('#pos-discount').value = '0';
      A('#pos-quantity').value = '1';
      A('#pos-amount').value = 'Rs. 0';
      const note = A('#pos-product-note');
      note.textContent = 'No product is available for this barcode.';
      note.className = 'pos-error';
    }
  };
  barcode.addEventListener('input', () => {
    clearTimeout(barcodeTimer);
    barcodeTimer = setTimeout(() => matchBarcode(true), 400);
  });
  const token = localStorage.getItem('dc_admin_token');
  if (!token) return;
  fetch('http://localhost:5000/api/products', { headers: { Authorization: `Bearer ${token}` } })
    .then(response => response.ok ? response.json() : null)
    .then(response => {
      if (!response?.data) return;
      const barcodeByApiId = new Map(response.data.map(product => [product.id, String(product.productCode || '')]));
      set('dc_products', products().map(product => ({ ...product, productCode: barcodeByApiId.has(product.apiId) ? barcodeByApiId.get(product.apiId) : product.productCode || '' })));
      matchBarcode();
    })
    .catch(() => {});
});

window.addEventListener('load', () => { if (document.body.dataset.page !== 'billing') return; document.addEventListener('click', event => { if (event.target.closest('[data-pos-tab="bills"]')) setTimeout(() => { const search = A('#pos-bill-search'); if (!search || search.closest('.pos-bill-search-box')) return; search.placeholder = 'Search Bill'; search.setAttribute('aria-label', 'Search saved bills'); search.insertAdjacentHTML('beforebegin', '<div class="pos-bill-search-box"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6"></circle><path d="m16 16 4 4"></path></svg></div>'); search.previousElementSibling.append(search); }, 0); }); });

// COD controls delivery availability and remembers every partner's prior status.
const codSettings = () => get('dc_cod_settings', { enabled: true });
const deliveryStatusKey = member => `${member.name || ''}|${member.phone || ''}`;
function setCashOnDelivery(enabled) { const team = get('dc_delivery_team', []), settings = codSettings(); if (!enabled) { const previous = {}; team.forEach(member => previous[deliveryStatusKey(member)] = member.status || 'Active'); set('dc_cod_delivery_statuses', previous); set('dc_delivery_team', team.map(member => ({ ...member, status: 'Inactive' }))); } else { const previous = get('dc_cod_delivery_statuses', {}); set('dc_delivery_team', team.map(member => ({ ...member, status: previous[deliveryStatusKey(member)] || member.status || 'Active' }))); } set('dc_cod_settings', { ...settings, enabled }); deliveryPage(); toast(`Cash on Delivery ${enabled ? 'enabled' : 'disabled'}`); }
const legacyDeliveryTeam = get('dc_delivery_team', []); if (legacyDeliveryTeam.some(member => String(member.status).toLowerCase() === 'off duty')) set('dc_delivery_team', legacyDeliveryTeam.map(member => String(member.status).toLowerCase() === 'off duty' ? { ...member, status: 'Inactive' } : member));
if (document.body.dataset.page === 'delivery') deliveryPage();


// Repair text that was saved with a Windows-1252/UTF-8 encoding mismatch.
function repairAdminTextEncoding(value) { if (!/[\u00c2\u00c3\u00e2\u00f0\u0152\u20ac]/.test(value)) return value; const cp1252 = { '\u20ac': 0x80, '\u201a': 0x82, '\u0192': 0x83, '\u201e': 0x84, '\u2026': 0x85, '\u2020': 0x86, '\u2021': 0x87, '\u02c6': 0x88, '\u2030': 0x89, '\u0160': 0x8a, '\u2039': 0x8b, '\u0152': 0x8c, '\u017d': 0x8e, '\u2018': 0x91, '\u2019': 0x92, '\u201c': 0x93, '\u201d': 0x94, '\u2022': 0x95, '\u2013': 0x96, '\u2014': 0x97, '\u02dc': 0x98, '\u2122': 0x99, '\u0161': 0x9a, '\u203a': 0x9b, '\u0153': 0x9c, '\u017e': 0x9e, '\u0178': 0x9f }; try { return new TextDecoder('utf-8', { fatal: true }).decode(Uint8Array.from(value, char => cp1252[char] ?? char.charCodeAt(0))) } catch { return value } }
function repairAdminTextNodes(root = document.body) { const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT); let node; while (node = walker.nextNode()) { const repaired = repairAdminTextEncoding(node.nodeValue); if (repaired !== node.nodeValue) node.nodeValue = repaired } }
window.addEventListener('load', () => { repairAdminTextNodes(); new MutationObserver(records => records.forEach(record => record.addedNodes.forEach(node => { if (node.nodeType === Node.TEXT_NODE) { const repaired = repairAdminTextEncoding(node.nodeValue); if (repaired !== node.nodeValue) node.nodeValue = repaired } else if (node.nodeType === Node.ELEMENT_NODE) repairAdminTextNodes(node) }))).observe(document.body, { childList: true, subtree: true }); });

// Keep the sidebar's own scrollbar at the same position while changing admin pages.
const adminSidebarScrollKey = 'dc_admin_sidebar_scroll';
window.addEventListener('load', () => { const nav = A('.side nav'); if (!nav) return; const restore = () => { const saved = Number(sessionStorage.getItem(adminSidebarScrollKey)); if (Number.isFinite(saved)) nav.scrollTop = saved }; restore(); requestAnimationFrame(restore); nav.addEventListener('scroll', () => sessionStorage.setItem(adminSidebarScrollKey, String(nav.scrollTop)), { passive: true }); });
