  draw(''); const search = A('#customer-manager-search'); search.addEventListener('input', event => draw(event.target.value)); A('#customer-manager-search-form').addEventListener('submit', event => { event.preventDefault(); draw(search.value); }); A('#customer-add').addEventListener('click', () => customerForm()); A('#customer-export').addEventListener('click', exportCustomersToExcel); A('#customer-bulk-upload').addEventListener('click', openCustomerBulkUpload); rows.addEventListener('click', event => { const edit = event.target.closest('[data-customer-edit]'), remove = event.target.closest('[data-customer-delete]'); if (edit) customerForm(Number(edit.dataset.customerEdit)); if (remove && confirm('Delete this customer account?')) { const index = Number(remove.dataset.customerDelete), updated = customerAccounts(); updated.splice(index, 1); set('dc_customers', updated); renderCustomerManagement(); toast('Customer account deleted'); } });
